mapper.update:
UPDATE tb_sy_code SET code_nm=#{row.name},use_yn=#{row.useYn},del_yn=#{row.delYn},code_val=#{row.codeVal},
  unit_nm=#{row.unitNm},add_val1=#{row.addVal1},add_val2=#{row.addVal2},mod_user_id=#{actor},mod_dttm=#{now}
WHERE code_grp_id=#{row.groupId} AND code=#{row.code}

mapper.select:
SELECT type,count FROM (
  SELECT '표기 대응' AS type,count(*) AS count FROM tb_sy_code_map WHERE code_grp_id=#{group} AND code=#{code}


      UNION ALL SELECT '개발자 직무',count(*) FROM tb_hr_dev WHERE job_cd=#{code} OR sub_job_cd=#{code}
      UNION ALL SELECT '후보 직무',count(*) FROM tb_hr_cand WHERE job_cd=#{code} OR sub_job_cd=#{code}
      UNION ALL SELECT '인원 계획',count(*) FROM tb_pj_mnpw_plan WHERE job_cd=#{code}
      UNION ALL SELECT '투입 직무',count(*) FROM tb_pj_asgn WHERE job_cd=#{code}
      UNION ALL SELECT '필요 인력',count(*) FROM tb_sl_opp_need WHERE job_cd=#{code}
      UNION ALL SELECT '추천 직무',count(*) FROM tb_sl_rcmd_log WHERE job_cd=#{code}
      UNION ALL SELECT '관련 JOB CSV',count(*) FROM tb_sy_code c WHERE c.del_yn='N'
        AND c.code_grp_id IN ('JOB','SKILL','RSM_JOB_KW') AND NOT(c.code_grp_id=#{group} AND c.code=#{code})
        AND EXISTS(SELECT 1 FROM unnest(string_to_array(c.add_val1,',')) v WHERE upper(btrim(v))=#{code})


      UNION ALL SELECT '개발자 등급',count(*) FROM tb_hr_dev WHERE grade_cd=#{code}
      UNION ALL SELECT '후보 등급',count(*) FROM tb_hr_cand WHERE grade_cd=#{code}
      UNION ALL SELECT '필요 등급',count(*) FROM tb_sl_opp_need WHERE grade_cd=#{code}
      UNION ALL SELECT '추천 등급',count(*) FROM tb_sl_rcmd_log WHERE req_grade_cd=#{code}

    UNION ALL SELECT '개발자 직위',count(*) FROM tb_hr_dev WHERE jbps_cd=#{code}

      UNION ALL SELECT '투입 연장',count(*) FROM tb_pj_asgn WHERE ext_psbl_cd=#{code}
      UNION ALL SELECT '연장 변경 이력',count(*) FROM tb_pj_asgn_hist h WHERE h.asgn_chg_type_cd='EXTP' AND
        (h.bfr_val=#{code} OR h.aft_val=#{code} OR EXISTS(SELECT 1 FROM tb_sy_code c WHERE c.code_grp_id=#{group} AND c.code=#{code} AND (h.bfr_val=c.code_nm OR h.aft_val=c.code_nm)))

    UNION ALL SELECT '재무 항목',count(*) FROM tb_fi_item WHERE sga_item_cd=#{code}
    UNION ALL SELECT '직접 경비',count(*) FROM tb_pj_drct_exps WHERE drct_exps_item_cd=#{code}
    UNION ALL SELECT '계약 변경',count(*) FROM tb_pj_proj_chg WHERE chg_item_cd=#{code}
    UNION ALL SELECT '이슈',count(*) FROM tb_pj_issue WHERE impr_cd=#{code}
    UNION ALL SELECT '프로젝트 단계',count(*) FROM tb_pj_step WHERE proj_step_cd=#{code}

      UNION ALL SELECT '후보 연락 상태',count(*) FROM tb_hr_cand WHERE cntc_stat_cd=#{code}
      UNION ALL SELECT '후보 연락 기록',count(*) FROM tb_hr_cand_cntc WHERE cntc_stat_cd=#{code}

    UNION ALL SELECT '후보 유입',count(*) FROM tb_hr_cand WHERE cand_src_cd=#{code}
    UNION ALL SELECT '투입 변경 사유',count(*) FROM tb_pj_asgn_hist WHERE asgn_chg_rsn_cd=#{code}

      UNION ALL SELECT '프로젝트 실주 사유',count(*) FROM tb_pj_proj WHERE lose_rsn_cd=#{code}
      UNION ALL SELECT '영업 실주 사유',count(*) FROM tb_sl_opp WHERE lose_rsn_cd=#{code}

    UNION ALL SELECT '추천 제외',count(*) FROM tb_sl_rcmd_log WHERE rcmd_excl_cd=#{code}
    UNION ALL SELECT '거래처 은행',count(*) FROM tb_bs_clnt WHERE bank_cd=#{code}
    UNION ALL SELECT '거래처 업종',count(*) FROM tb_bs_clnt WHERE induty_cd=#{code}

      UNION ALL SELECT '개발자 스킬',count(*) FROM tb_hr_dev_skill s WHERE s.skill_nm IN (
        SELECT code_nm FROM tb_sy_code WHERE code_grp_id=#{group} AND code=#{code}
        UNION SELECT bfr_val FROM tb_sy_chg_hist WHERE trgt_tbl_nm='TB_SY_CODE' AND trgt_key=#{group}||':'||#{code} AND chg_item_nm='CODE_NM'
        UNION SELECT aft_val FROM tb_sy_chg_hist WHERE trgt_tbl_nm='TB_SY_CODE' AND trgt_key=#{group}||':'||#{code} AND chg_item_nm='CODE_NM')
      UNION ALL SELECT '후보 스킬',count(*) FROM tb_hr_cand_skill s WHERE s.skill_nm IN (
        SELECT code_nm FROM tb_sy_code WHERE code_grp_id=#{group} AND code=#{code}
        UNION SELECT bfr_val FROM tb_sy_chg_hist WHERE trgt_tbl_nm='TB_SY_CODE' AND trgt_key=#{group}||':'||#{code} AND chg_item_nm='CODE_NM'
        UNION SELECT aft_val FROM tb_sy_chg_hist WHERE trgt_tbl_nm='TB_SY_CODE' AND trgt_key=#{group}||':'||#{code} AND chg_item_nm='CODE_NM')


) refs WHERE count > 0
